from collections import defaultdict

def solve():
    import sys
    input = sys.stdin.read
    data = input().split()
    if not data:
        return
    n = int(data[0])
    passwords = data[1:1+n]

    # 特判：所有口令完全相同
    first = passwords[0]
    all_same = True
    for pwd in passwords:
        if pwd != first:
            all_same = False
            break
    if all_same:
        print(n - 1)
        return

    # 统计每个口令的连续段长度
    seg = defaultdict(list)
    cur_pwd = passwords[0]
    cur_len = 1
    for i in range(1, n):
        if passwords[i] == cur_pwd:
            cur_len += 1
        else:
            seg[cur_pwd].append(cur_len)
            cur_pwd = passwords[i]
            cur_len = 1
    seg[cur_pwd].append(cur_len)  # 处理最后一段

    max_ans = 0
    for lengths in seg.values():
        lengths.sort(reverse=True)
        if len(lengths) == 1:
            max_ans = max(max_ans, lengths[0])
        else:
            max_ans = max(max_ans, lengths[0] + lengths[1])
    print(max_ans)

if __name__ == "__main__":
    solve()
